record.field:
pharmacist_group = env.ref('base_hospital_management.base_hospital_management_group_pharmacist', raise_if_not_found=False)
if pharmacist_group:
    orderpoints = env['stock.warehouse.orderpoint'].search([])
    low_items = []
    seen = set()
    for op in orderpoints:
        if op.product_min_qty <= 0:
            continue
        key = op.product_id.id
        if key in seen:
            continue
        seen.add(key)
        qty = op.product_id.qty_available
        if qty <= op.product_min_qty:
            low_items.append(op.product_id.name + ': ' + str(int(qty)) + ' (min: ' + str(int(op.product_min_qty)) + ')')
    if low_items:
        env.cr.execute(
            "SELECT u.partner_id FROM res_users u JOIN res_groups_users_rel r ON r.uid = u.id WHERE r.gid = %s AND u.active = true",
            (pharmacist_group.id,)
        )
        partner_ids = [row[0] for row in env.cr.fetchall()]
        if partner_ids:
            text = 'Low Stock Alert - Please raise a Purchase Orders:\n' + '\n'.join('* ' + i for i in low_items)
            env['res.partner'].browse(partner_ids[0]).sudo().message_post(
                body=text,
                subject='Low Stock Alert',
                message_type='comment',
                subtype_xmlid='mail.mt_comment',
                partner_ids=partner_ids,
            )
